export const envelope = [18, 16, 16];

export default function build(api) {
  const [sizeX, sizeY, sizeZ] = api.size;

  // Safe setter with envelope bounds checking
  function set(x, y, z, block) {
    if (x >= 0 && x < sizeX && y >= 0 && y < sizeY && z >= 0 && z < sizeZ) {
      api.set(x, y, z, block);
    }
  }

  // Ground support to anchor footings to the terrain
  function supportGround(x, z, startY, block) {
    const gh = Math.min(0, Math.floor(api.heightAt(x, z)));
    for (let y = startY; y >= gh; y--) {
      set(x, y, z, block);
    }
  }

  // 3D Bresenham line for guy wires, cables, and rigging
  function drawLine(x0, y0, z0, x1, y1, z1, block) {
    const dx = Math.abs(x1 - x0);
    const dy = Math.abs(y1 - y0);
    const dz = Math.abs(z1 - z0);
    const steps = Math.max(dx, dy, dz);
    if (steps === 0) {
      set(x0, y0, z0, block);
      return;
    }
    for (let i = 0; i <= steps; i++) {
      const x = Math.round(x0 + (x1 - x0) * (i / steps));
      const y = Math.round(y0 + (y1 - y0) * (i / steps));
      const z = Math.round(z0 + (z1 - z0) * (i / steps));
      set(x, y, z, block);
    }
  }

  // Theme palette resolution with industrial logging fallbacks
  const logZ = api.theme.wood.log ? `${api.theme.wood.log.split('[')[0]}[axis=z]` : "minecraft:spruce_log[axis=z]";
  const logX = api.theme.wood.log ? `${api.theme.wood.log.split('[')[0]}[axis=x]` : "minecraft:spruce_log[axis=x]";
  const logY = api.theme.wood.log ? `${api.theme.wood.log.split('[')[0]}[axis=y]` : "minecraft:spruce_log[axis=y]";
  const strippedLogZ = api.theme.wood.stripped ? `${api.theme.wood.stripped.split('[')[0]}[axis=z]` : "minecraft:stripped_spruce_log[axis=z]";
  const strippedLogY = api.theme.wood.stripped ? `${api.theme.wood.stripped.split('[')[0]}[axis=y]` : "minecraft:stripped_spruce_log[axis=y]";
  const planks = api.theme.wood.planks || "minecraft:spruce_planks";
  const slab = api.theme.wood.slab || "minecraft:spruce_slab[type=bottom]";
  const slabTop = api.theme.wood.slab ? `${api.theme.wood.slab.split('[')[0]}[type=top]` : "minecraft:spruce_slab[type=top]";

  const stairsBase = api.theme.wood.stairs ? api.theme.wood.stairs.split('[')[0] : "minecraft:spruce_stairs";
  const stairsN = `${stairsBase}[facing=north,half=bottom]`;
  const stairsS = `${stairsBase}[facing=south,half=bottom]`;
  const stairsE = `${stairsBase}[facing=east,half=bottom]`;
  const stairsW = `${stairsBase}[facing=west,half=bottom]`;
  const stairsTopN = `${stairsBase}[facing=north,half=top]`;
  const stairsTopS = `${stairsBase}[facing=south,half=top]`;
  const stairsTopE = `${stairsBase}[facing=east,half=top]`;
  const stairsTopW = `${stairsBase}[facing=west,half=top]`;

  const fence = api.theme.wood.fence || "minecraft:spruce_fence";
  const trapdoor = api.theme.wood.trapdoor || "minecraft:spruce_trapdoor";

  // --- 1. SKID TRAIL & GROUND FOUNDATION (Y=0) ---
  for (let z = 0; z <= 15; z++) {
    for (let x = 3; x <= 14; x++) {
      supportGround(x, z, 0, "minecraft:coarse_dirt");
    }
  }

  // Embedded transverse corduroy skid poles along the trail
  const corduroyZs = [0, 2, 4, 6];
  for (const cz of corduroyZs) {
    for (let cx = 5; cx <= 12; cx++) {
      set(cx, 0, cz, logX);
    }
  }

  // --- 2. HEAVY TIMBER SLED RUNNERS & PLATFORM (Y=1..2) ---
  // Left runner (X=4..5) and Right runner (X=12..13), Z=7..15
  for (let z = 7; z <= 15; z++) {
    set(4, 1, z, strippedLogZ);
    set(5, 1, z, strippedLogZ);
    set(12, 1, z, strippedLogZ);
    set(13, 1, z, strippedLogZ);
    supportGround(4, z, 1, "minecraft:coarse_dirt");
    supportGround(5, z, 1, "minecraft:coarse_dirt");
    supportGround(12, z, 1, "minecraft:coarse_dirt");
    supportGround(13, z, 1, "minecraft:coarse_dirt");
  }

  // Curved upturned sled noses at front (Z=7)
  set(4, 2, 7, stairsS);
  set(5, 2, 7, stairsS);
  set(12, 2, 7, stairsS);
  set(13, 2, 7, stairsS);

  // Heavy cross bunks tying runners together
  const bunkZs = [7, 10, 14];
  for (const bz of bunkZs) {
    for (let bx = 4; bx <= 13; bx++) {
      set(bx, 1, bz, logX);
    }
  }

  // Heavy wood decking
  for (let z = 8; z <= 14; z++) {
    for (let x = 5; x <= 12; x++) {
      set(x, 2, z, planks);
    }
  }
  for (let z = 8; z <= 14; z++) {
    set(4, 2, z, slabTop);
    set(13, 2, z, slabTop);
  }

  // --- 3. VERTICAL IRON BOILER & SMOKESTACK (Z=11..12, X=6..7, Y=3..12) ---
  // Firebox base (Y=3)
  set(6, 3, 11, "minecraft:blast_furnace[facing=north,lit=true]");
  set(7, 3, 11, "minecraft:blast_furnace[facing=north,lit=true]");
  set(6, 3, 12, "minecraft:iron_block");
  set(7, 3, 12, "minecraft:iron_block");

  // Boiler barrel body (Y=4..6)
  for (let by = 4; by <= 6; by++) {
    set(6, by, 11, "minecraft:iron_block");
    set(7, by, 11, "minecraft:iron_block");
    set(6, by, 12, "minecraft:iron_block");
    set(7, by, 12, "minecraft:iron_block");
  }

  // Boiler accessories: water gauge, pressure valve, steam manifold
  set(5, 4, 11, "minecraft:stone_button[facing=west]");
  set(6, 4, 10, "minecraft:tripwire_hook[facing=north]");
  set(7, 4, 10, "minecraft:lever[facing=north,face=wall]");
  set(8, 4, 11, "minecraft:stone_button[facing=east]");

  // Boiler top transition & dome (Y=7)
  set(6, 7, 11, "minecraft:cauldron");
  set(7, 7, 11, "minecraft:hopper[facing=down]");
  set(6, 7, 12, "minecraft:iron_block");
  set(7, 7, 12, "minecraft:hopper[facing=down]");

  // Tall vertical smokestack (Y=8..12)
  set(6, 8, 11, "minecraft:cauldron");
  set(6, 9, 11, "minecraft:hopper[facing=down]");
  set(6, 10, 11, "minecraft:iron_bars");
  set(6, 11, 11, "minecraft:iron_bars");
  set(6, 12, 11, "minecraft:iron_bars");
  set(6, 13, 11, "minecraft:iron_trapdoor[facing=north,half=top]");

  // Steam safety exhaust blow-off pipe
  set(7, 8, 12, "minecraft:iron_bars");
  set(7, 9, 12, "minecraft:iron_bars");
  set(7, 10, 12, "minecraft:chain[axis=y]");

  // --- 4. ENGINE CYLINDERS, GEAR TRAIN & WINCH SPOOL DRUMS (Z=9..10, Y=3..5) ---
  // Steam cylinders on both sides
  set(5, 3, 11, "minecraft:hopper[facing=north]");
  set(5, 3, 10, "minecraft:piston[facing=north]");
  set(8, 3, 11, "minecraft:hopper[facing=north]");
  set(8, 3, 10, "minecraft:piston[facing=north]");

  // Reduction gear crank & flywheels
  set(5, 3, 9, "minecraft:grindstone[face=floor,facing=east]");
  set(8, 3, 9, "minecraft:grindstone[face=floor,facing=west]");

  // Main Cable Winch Drum (Spool at X=6..7, Z=9, Y=3..4)
  set(6, 3, 9, "minecraft:chain[axis=x]");
  set(7, 3, 9, "minecraft:chain[axis=x]");
  set(6, 4, 9, "minecraft:chain[axis=y]");
  set(7, 4, 9, "minecraft:chain[axis=y]");
  set(5, 4, 9, "minecraft:iron_trapdoor[facing=east,half=bottom,open=true]");
  set(8, 4, 9, "minecraft:iron_trapdoor[facing=west,half=bottom,open=true]");

  // Haulback auxiliary drum (X=9, Z=9, Y=3..4)
  set(9, 3, 9, "minecraft:chain[axis=y]");
  set(9, 4, 9, "minecraft:iron_bars");
  set(9, 3, 10, "minecraft:grindstone[face=floor,facing=north]");

  // Engineer controls, throttle, and brake levers on the platform
  set(8, 3, 12, "minecraft:lever[face=floor,facing=north]");
  set(7, 3, 13, "minecraft:lever[face=floor,facing=north]");
  set(8, 3, 13, "minecraft:heavy_weighted_pressure_plate");

  // --- 5. DECK WORKSPACE, WATER BARREL & FIREWOOD CORDAGE ---
  // Boiler firewood bunker (X=10..12, Z=11..13)
  for (let fz = 11; fz <= 13; fz++) {
    set(10, 3, fz, logX);
    set(11, 3, fz, logX);
    set(10, 4, fz, slab);
  }
  set(12, 3, 11, trapdoor);
  set(12, 3, 12, trapdoor);
  set(12, 3, 13, trapdoor);

  // Boiler feedwater tank / barrel
  set(11, 3, 9, "minecraft:cauldron");
  set(10, 3, 8, "minecraft:chest[facing=north]");
  set(11, 3, 8, "minecraft:crafting_table");

  // --- 6. TIMBER SHELTER CANOPY OVER MACHINE (Y=3..8) ---
  // Heavy timber canopy posts
  const postCorners = [
    [4, 8], [4, 14], [13, 8], [13, 14]
  ];
  for (const [px, pz] of postCorners) {
    for (let py = 3; py <= 6; py++) {
      set(px, py, pz, fence);
    }
  }

  // Canopy roof rafters (Y=7)
  for (let cx = 4; cx <= 13; cx++) {
    set(cx, 7, 8, logX);
    set(cx, 7, 14, logX);
  }
  for (let cz = 8; cz <= 14; cz++) {
    set(4, 7, cz, logZ);
    set(13, 7, cz, logZ);
  }

  // Slanted canopy plank & slab cover with opening for smokestack
  for (let cz = 9; cz <= 13; cz++) {
    for (let cx = 5; cx <= 12; cx++) {
      // Leave clearance around smokestack (X=6..7, Z=11..12)
      if ((cx === 6 || cx === 7) && (cz === 11 || cz === 12)) {
        continue;
      }
      set(cx, 8, cz, slab);
    }
  }
  // Hanging oil lantern on canopy frame
  set(5, 6, 9, "minecraft:lantern[hanging=true]");

  // --- 7. GUYED TIMBER SPAR DERRICK / A-FRAME (Y=2..13) ---
  // Left Spar Mast: starts at (4, 2, 7) climbs to apex at (8, 12, 5)
  drawLine(4, 2, 7, 8, 12, 5, strippedLogY);
  // Right Spar Mast: starts at (13, 2, 7) climbs to apex at (9, 12, 5)
  drawLine(13, 2, 7, 9, 12, 5, strippedLogY);

  // Cross-tie brace on A-frame spar
  for (let bx = 6; bx <= 11; bx++) {
    set(bx, 6, 6, logX);
  }

  // Apex headcap and rigging collars (Y=12..13, Z=5)
  set(8, 12, 5, logX);
  set(9, 12, 5, logX);
  set(8, 13, 5, "minecraft:chain[axis=x]");
  set(9, 13, 5, "minecraft:chain[axis=x]");

  // Heavy steel guy lines (chains) anchoring mast apex back to sled and ground
  drawLine(8, 13, 5, 4, 3, 14, "minecraft:chain[axis=y]");
  drawLine(9, 13, 5, 13, 3, 14, "minecraft:chain[axis=y]");

  // Front guy line anchors to forest ground
  drawLine(8, 12, 5, 2, 1, 2, "minecraft:chain[axis=y]");
  drawLine(9, 12, 5, 15, 1, 2, "minecraft:chain[axis=y]");
  supportGround(2, 2, 1, "minecraft:stone_bricks");
  supportGround(15, 2, 1, "minecraft:stone_bricks");
  set(2, 1, 2, "minecraft:anvil[facing=north]");
  set(15, 1, 2, "minecraft:anvil[facing=north]");

  // Main Bull Block (Heavy Pulley Sheave) suspended from apex
  set(8, 11, 5, "minecraft:grindstone[face=ceiling,facing=north]");
  set(9, 11, 5, "minecraft:chain[axis=y]");

  // Haulage cable from Winch Drum (6, 4, 9) up to Bull Block (8, 11, 5)
  drawLine(6, 4, 9, 8, 11, 5, "minecraft:chain[axis=y]");

  // --- 8. THE MAMMOTH DRAGGED REDWOOD LOG (Z=0..6, X=7..9, Y=1..3) ---
  // Colossal trunk cylinder 3 blocks wide x 3 blocks high x 6 blocks long
  for (let lz = 0; lz <= 5; lz++) {
    // Solid 3x3 circular cross-section
    set(8, 2, lz, logZ); // Center core
    set(8, 3, lz, logZ); // Top
    set(8, 1, lz, logZ); // Bottom
    set(7, 2, lz, logZ); // Left
    set(9, 2, lz, logZ); // Right

    // Beveled corners for round trunk profile
    set(7, 3, lz, stairsE);
    set(9, 3, lz, stairsW);
    set(7, 1, lz, stairsTopE);
    set(9, 1, lz, stairsTopW);
  }

  // Crosscut log end at Z=0 showing giant growth ring core
  set(8, 2, 0, strippedLogZ);

  // Sniped log nose at Z=5..6 (beveled front so log rides over stumps)
  set(8, 3, 5, stairsS);
  set(7, 3, 5, stairsS);
  set(9, 3, 5, stairsS);
  set(8, 2, 6, stairsS);
  set(8, 1, 6, logZ);
  set(7, 2, 6, stairsE);
  set(9, 2, 6, stairsW);

  // Heavy Choker Rigging & Shackle Bell around log nose at Z=5
  set(7, 3, 5, "minecraft:chain[axis=z]");
  set(9, 3, 5, "minecraft:chain[axis=z]");
  set(7, 2, 5, "minecraft:chain[axis=y]");
  set(9, 2, 5, "minecraft:chain[axis=y]");
  set(7, 1, 5, "minecraft:chain[axis=x]");
  set(9, 1, 5, "minecraft:chain[axis=x]");

  // Choker hook / bell coupling point at (8, 4, 5)
  set(8, 4, 5, "minecraft:anvil[facing=north]");

  // Mainline hauling wire rope from Bull Block (8, 11, 5) down to Choker Bell (8, 4, 5)
  drawLine(8, 11, 5, 8, 4, 5, "minecraft:chain[axis=y]");

  // --- 9. FORESTRY TOOLS & CAMP DETAILS ---
  // Heavy logging peavey / crosscut saw leaned against the derrick
  set(4, 3, 7, "minecraft:iron_bars");
  set(4, 4, 7, "minecraft:iron_bars");
  // Chopping block with ax
  set(11, 2, 7, logY);
  set(11, 3, 7, "minecraft:iron_trapdoor[facing=north,half=bottom]");
  // Oil lantern on donkey sled post
  set(13, 3, 8, "minecraft:lantern[hanging=false]");

  return {
    name: "Steam Donkey Winch",
    seatY: 0,
    anchors: {
      front: [8, 1, 0]
    }
  };
}

