export const envelope = [24, 11, 10];

export default function build(api) {
  const { theme } = api;
  const W = envelope[0];
  const H = envelope[1];
  const D = envelope[2];

  // 3D placement grid for deterministic, bounds-safe emission
  const grid = Array.from({ length: W }, () =>
    Array.from({ length: H }, () =>
      new Array(D).fill(null)
    )
  );

  function put(x, y, z, block) {
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
      grid[x][y][z] = block;
    }
  }

  // Helpers to safely adapt theme blocks with correct block states
  function getLog(themeLog, axis = "x") {
    const base = (themeLog || "minecraft:spruce_log").split("[")[0];
    return `${base}[axis=${axis}]`;
  }

  function getStripped(themeStripped, axis = "x") {
    const base = (themeStripped || "minecraft:stripped_spruce_log").split("[")[0];
    return `${base}[axis=${axis}]`;
  }

  function getStairs(themeStairs, facing = "north", half = "bottom", shape = "straight") {
    const base = (themeStairs || "minecraft:spruce_stairs").split("[")[0];
    return `${base}[facing=${facing},half=${half},shape=${shape}]`;
  }

  function getSlab(themeSlab, type = "bottom") {
    const base = (themeSlab || "minecraft:spruce_slab").split("[")[0];
    return `${base}[type=${type}]`;
  }

  function getTrapdoor(themeTrapdoor, facing = "north", half = "bottom", open = false) {
    const base = (themeTrapdoor || "minecraft:spruce_trapdoor").split("[")[0];
    return `${base}[facing=${facing},half=${half},open=${open}]`;
  }

  function getFence(themeFence) {
    return (themeFence || "minecraft:spruce_fence").split("[")[0];
  }

  function getPlanks(themePlanks) {
    return themePlanks || "minecraft:spruce_planks";
  }

  // Plugin variation mode: 4 distinct narrative instances
  const inst = (api.instance.index || 0) % 4;

  // Skid locations along X per instance
  const skidConfigs = [
    [3, 8, 14, 19],
    [4, 9, 15, 20],
    [3, 8, 13, 18],
    [2, 6, 13, 19]
  ];
  const skids = skidConfigs[inst];

  // Trunk span along X
  const trunkBounds = [
    { start: 2, end: 21 },
    { start: 3, end: 22 },
    { start: 2, end: 20 },
    { start: 1, end: 21 }
  ];
  const { start: xStart, end: xEnd } = trunkBounds[inst];

  // 1. Skidway & Terrain Foundations (seatY = 2)
  for (const sx of skids) {
    for (let z = 1; z <= 8; z++) {
      const terrainOffset = Math.max(-2, Math.min(1, Math.round(api.heightAt(sx, z))));
      const groundY = Math.max(0, 2 + terrainOffset);

      // Skirt foundation down to ground
      for (let y = groundY; y < 2; y++) {
        put(sx, y, z, getLog(theme.wood.log, "y"));
      }

      // Primary skid cross-timber (oriented along Z)
      put(sx, 2, z, getLog(theme.wood.log, "z"));

      // Chock wedges holding the trunk curvature
      if (z === 2) {
        put(sx, 3, 2, getStairs(theme.wood.stairs, "south", "bottom"));
      } else if (z === 7) {
        put(sx, 3, 7, getStairs(theme.wood.stairs, "north", "bottom"));
      }
    }
  }

  // Longitudinal skidway guide runners
  for (let x = skids[0]; x <= skids[skids.length - 1]; x++) {
    if (!grid[x][2][1]) put(x, 2, 1, getLog(theme.wood.log, "x"));
    if (!grid[x][2][8]) put(x, 2, 8, getLog(theme.wood.log, "x"));
  }
  put(skids[0], 3, 1, getFence(theme.wood.fence));
  put(skids[skids.length - 1], 3, 1, getFence(theme.wood.fence));
  put(skids[0], 3, 8, getFence(theme.wood.fence));
  put(skids[skids.length - 1], 3, 8, getFence(theme.wood.fence));

  // 2. Colossal Trunk Geometry
  const cy = 5.5;
  const cz = 4.5;

  function isKerfCut(x, y, z) {
    if (inst === 0) {
      if (x === 10 && y >= 5 && z >= 2 && z <= 7) return true;
      if (x === 16 && y >= 7 && z >= 3 && z <= 6) return true;
    } else if (inst === 1) {
      if ((z === 4 || z === 5) && x >= 6 && x <= 17) {
        if (y === 8) return true;
        if (y === 7 && x >= 9 && x <= 14) return true;
      }
    } else if (inst === 2) {
      if (x === 8 && (y === 5 || y === 6) && z === 2) return true;
    } else if (inst === 3) {
      if (x === 6 && y >= 4 && z >= 2 && z <= 7) return true;
      if (x === 14 && y >= 5 && z >= 2 && z <= 7) return true;
      if (x === 19 && y >= 7 && z >= 3 && z <= 6) return true;
    }
    return false;
  }

  for (let x = xStart; x <= xEnd; x++) {
    const progress = (x - xStart) / (xEnd - xStart);
    const buttress = Math.pow(1.0 - progress, 2) * 0.35;
    const ry = 2.55 + buttress - 0.22 * progress;
    const rz = 2.65 + buttress - 0.22 * progress;

    for (let y = 3; y <= 8; y++) {
      for (let z = 2; z <= 7; z++) {
        const dy = (y - cy) / ry;
        const dz = (z - cz) / rz;
        const theta = Math.atan2(dy, dz);
        const noise = 0.07 * Math.sin(x * 1.1 + theta * 3) + 0.04 * Math.cos(theta * 5);
        const dist = Math.sqrt(dy * dy + dz * dz);

        if (dist <= 1.0 + noise) {
          if (isKerfCut(x, y, z)) continue;

          const isBuckedFace = (x === xStart || x === xEnd || (inst === 3 && (x === 5 || x === 7)));

          if (isBuckedFace) {
            if (dist > 0.82 + noise) {
              put(x, y, z, getLog(theme.wood.log, "x"));
            } else {
              const ring = Math.floor(dist * 5.2) % 2 === 0;
              put(x, y, z, ring ? getStripped(theme.wood.stripped, "x") : getPlanks(theme.wood.planks));
            }
          } else {
            if (dist > 0.78 + noise) {
              const peelThreshold = (inst === 1) ? -0.15 : 0.52;
              const peeled = Math.sin(x * 0.9 + y * 1.7 + z * 1.3) > peelThreshold;
              put(x, y, z, peeled ? getStripped(theme.wood.stripped, "x") : getLog(theme.wood.log, "x"));
            } else {
              put(x, y, z, getStripped(theme.wood.stripped, "x"));
            }
          }
        }
      }
    }
  }

  // 3. Narrative Instance Details

  if (inst === 0) {
    // Two-man bucking saw inside kerf at x = 10
    for (let z = 3; z <= 6; z++) {
      put(10, 5, z, "minecraft:iron_bars[east=true,west=true]");
    }
    put(10, 5, 2, getFence(theme.wood.fence));
    put(10, 5, 7, getFence(theme.wood.fence));
    put(10, 8, 4, "minecraft:heavy_weighted_pressure_plate");
    put(10, 8, 5, "minecraft:heavy_weighted_pressure_plate");

    // Bucker's springboard staging platform
    put(10, 4, 1, getPlanks(theme.wood.planks));
    put(9, 4, 1, getSlab(theme.wood.slab, "top"));
    put(11, 4, 1, getSlab(theme.wood.slab, "top"));
    put(10, 3, 1, getStairs(theme.wood.stairs, "south", "top"));
    put(9, 3, 1, "minecraft:ladder[facing=south]");
    put(9, 2, 1, "minecraft:ladder[facing=south]");

    // Bucker's lantern & sawdust heaps
    put(15, 8, 4, "minecraft:lantern[hanging=false]");
    put(10, 3, 3, getSlab(theme.wood.slab, "bottom"));
    put(10, 3, 6, getSlab(theme.wood.slab, "bottom"));
    put(3, 3, 2, "minecraft:chain[axis=y]");
    put(19, 3, 2, "minecraft:chain[axis=y]");

  } else if (inst === 1) {
    // Heavy iron splitting wedges along top radial split
    put(8, 7, 4, "minecraft:iron_block");
    put(8, 8, 4, "minecraft:anvil[facing=north]");
    put(12, 7, 5, "minecraft:iron_block");
    put(12, 8, 5, "minecraft:heavy_weighted_pressure_plate");
    put(15, 7, 4, "minecraft:iron_bars[east=true,west=true]");
    put(15, 8, 4, "minecraft:iron_bars[east=true,west=true]");

    // Timber cribbing stacks beneath end skids
    for (let z = 3; z <= 6; z++) {
      put(4, 1, z, getLog(theme.wood.log, "x"));
      put(20, 1, z, getLog(theme.wood.log, "x"));
    }

    // Peeled bark sheets on ground/skidway
    put(6, 3, 1, getTrapdoor(theme.wood.trapdoor, "north", "bottom", false));
    put(7, 3, 1, getSlab(theme.wood.slab, "bottom"));
    put(16, 8, 6, getSlab(theme.wood.slab, "bottom"));
    put(13, 8, 3, "minecraft:anvil[facing=east]");

  } else if (inst === 2) {
    // Massive cut limb stub branching upward
    put(13, 7, 6, getLog(theme.wood.log, "y"));
    put(14, 7, 6, getLog(theme.wood.log, "y"));
    put(13, 8, 6, getLog(theme.wood.log, "y"));
    put(14, 8, 6, getLog(theme.wood.log, "y"));
    put(13, 8, 7, getLog(theme.wood.log, "y"));
    put(14, 8, 7, getLog(theme.wood.log, "y"));
    put(13, 9, 6, getStripped(theme.wood.stripped, "y"));
    put(14, 9, 6, getLog(theme.wood.log, "y"));
    put(13, 9, 7, getLog(theme.wood.log, "y"));
    put(14, 9, 7, getLog(theme.wood.log, "y"));
    put(13, 10, 6, getSlab(theme.wood.slab, "bottom"));
    put(14, 10, 6, getSlab(theme.wood.slab, "bottom"));
    put(13, 10, 7, getSlab(theme.wood.slab, "bottom"));
    put(14, 10, 7, getSlab(theme.wood.slab, "bottom"));

    // Heavy wrap-around skid chains
    for (let z = 2; z <= 7; z++) put(5, 2, z, "minecraft:chain[axis=z]");
    for (let y = 3; y <= 7; y++) {
      put(5, y, 2, "minecraft:chain[axis=y]");
      put(5, y, 7, "minecraft:chain[axis=y]");
      put(18, y, 2, "minecraft:chain[axis=y]");
      put(18, y, 7, "minecraft:chain[axis=y]");
    }
    for (let z = 3; z <= 6; z++) {
      put(5, 8, z, "minecraft:chain[axis=z]");
      put(18, 8, z, "minecraft:chain[axis=z]");
    }
    put(5, 2, 0, "minecraft:iron_bars[north=true,south=true]");

    // Undercut axed notch & grease lantern
    put(8, 5, 2, getStairs(theme.wood.stairs, "south", "top"));
    put(8, 6, 2, getStairs(theme.wood.stairs, "south", "bottom"));
    put(8, 5, 3, getStripped(theme.wood.stripped, "x"));
    put(8, 6, 3, getStripped(theme.wood.stripped, "x"));
    put(3, 3, 1, "minecraft:lantern[hanging=false]");

  } else if (inst === 3) {
    // Sawdust accumulation under through-cut round
    put(6, 3, 3, getSlab(theme.wood.slab, "bottom"));
    put(6, 3, 6, getSlab(theme.wood.slab, "bottom"));

    // Crosscut saw in kerf at x = 14
    for (let z = 3; z <= 6; z++) {
      put(14, 5, z, "minecraft:iron_bars[east=true,west=true]");
    }
    put(14, 5, 2, getFence(theme.wood.fence));
    put(14, 5, 7, getFence(theme.wood.fence));

    // Splitting wedge at x = 19
    put(19, 8, 4, "minecraft:anvil[facing=north]");
    put(19, 8, 5, "minecraft:heavy_weighted_pressure_plate");

    // Bucking measure rod on top of trunk
    for (let x = 8; x <= 17; x++) {
      if (x !== 14) put(x, 8, 3, getFence(theme.wood.fence));
    }

    // Cant hook lever leaning against cut round
    put(5, 2, 1, getLog(theme.wood.log, "y"));
    put(5, 3, 1, "minecraft:iron_bars[north=true,south=true]");
    put(5, 4, 1, getFence(theme.wood.fence));
  }

  // 4. Subtle moss & bark details on upper surfaces
  for (let x = xStart; x <= xEnd; x++) {
    for (let z = 2; z <= 7; z++) {
      if (grid[x][7][z] && !grid[x][8][z] && api.random() < 0.18) {
        put(x, 8, z, "minecraft:moss_carpet");
      }
    }
  }

  // Deterministic emit loop
  for (let y = 0; y < H; y++) {
    for (let z = 0; z < D; z++) {
      for (let x = 0; x < W; x++) {
        const block = grid[x][y][z];
        if (block !== null) {
          api.set(x, y, z, block);
        }
      }
    }
  }

  return {
    name: "felled_colossal_redwood",
    seatY: 2,
    anchors: {
      front: [12, 2, 0],
      skidway: [12, 2, 0]
    }
  };
}

